<script lang="ts">import SelectRoot from '@fex-design/svelte/primitive/select'; import SelectTrigger from '@fex-design/svelte/primitive/select-trigger'; import SelectContent from '@fex-design/svelte/primitive/select-content'; const options=[{value:'react',label:'React'},{value:'vue',label:'Vue'},{value:'solid',label:'Solid'}]; const filter=(keyword:string,option:{label:string})=>{let from=0;return [...keyword.toLowerCase()].every(character=>{const index=option.label.toLowerCase().indexOf(character,from);from=index+1;return index>=0})}</script><SelectRoot {options} showSearch filterOption={filter}><SelectTrigger class="w-72" placeholder="输入 rt 试试"/><SelectContent/></SelectRoot>
